//! phpstan.neon resolution against the real PHPStan 2.3.1 (`scripts/phpstan-config.php`, regenerated by
//! `scripts/export-phpstan-config-fixtures.php`): edge-case configs in tests/fixtures/config/<case>/ and the corpus
//! projects' own configs (tests/fixtures/config-corpus/*.json; needs `scripts/corpus.sh` and `.oracle/phpstan`).

mod common;

use std::path::{Path, PathBuf};

use common::{dumped, fixture, placeholders};
use pun_phpstan::config::{Options, resolve};
use serde_json::{Value as J, json};

const ROOT: &str = "/pun-root";
const TMP: &str = "/pun-tmp";

fn options(cwd: &Path, case: &J, base: Options) -> Options {
    let mut o = Options {
        cwd: cwd.to_string_lossy().into_owned(),
        sys_temp_dir: TMP.into(),
        env: Vec::new(),
        ..base
    };
    let args: Vec<String> = case["args"]
        .as_array()
        .map(|a| a.iter().map(|x| x.as_str().unwrap().to_string()).collect())
        .unwrap_or_default();
    let mut it = args.into_iter();
    while let Some(a) = it.next() {
        match a.as_str() {
            "-c" => o.config = it.next(),
            "-l" => o.level = it.next(),
            "--generate-baseline" => o.generate_baseline = it.next(),
            "--generated-config" => {
                o.generated_config = it
                    .next()
                    .map(|g| cwd.join(g).to_string_lossy().into_owned());
            }
            _ => o.paths.push(a),
        }
    }
    if let Some(env) = case["env"].as_object() {
        o.env = env
            .iter()
            .map(|(k, v)| (k.clone(), v.as_str().unwrap().to_string()))
            .collect();
    }
    o
}

fn got(o: &Options, map: &[(&str, &str)]) -> J {
    match resolve(o) {
        Ok(r) => placeholders(
            json!({ "parameters": dumped(&pun_phpstan::Value::Array(r.parameters)) }),
            map,
        ),
        Err(e) => placeholders(json!({ "error": e }), map),
    }
}

/// The differing top-level parameters (or the whole result when one side is an error).
fn diff(want: &J, got: &J) -> Option<String> {
    if want == got {
        return None;
    }
    let (Some(w), Some(g)) = (
        want["parameters"].as_object(),
        got["parameters"].as_object(),
    ) else {
        return Some(format!("want {want:#}\ngot  {got:#}"));
    };
    let mut out = Vec::new();
    for k in w.keys().chain(g.keys().filter(|k| !w.contains_key(*k))) {
        if w.get(k) != g.get(k) {
            out.push(format!(
                "  {k}:\n    want {}\n    got  {}",
                w.get(k).unwrap_or(&J::Null),
                g.get(k).unwrap_or(&J::Null)
            ));
        }
    }
    Some(out.join("\n"))
}

#[test]
fn edge_case_configs() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/config");
    let mut failures = Vec::new();
    let mut cases: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    cases.sort();
    for case_dir in &cases {
        let case: J =
            serde_json::from_str(&std::fs::read_to_string(case_dir.join("case.json")).unwrap())
                .unwrap();
        let want: J =
            serde_json::from_str(&std::fs::read_to_string(case_dir.join("expected.json")).unwrap())
                .unwrap();
        let cwd = case_dir.to_string_lossy().into_owned();
        let base = Options {
            phar: format!("{ROOT}/phpstan.phar"),
            ..Options::default()
        };
        let o = options(case_dir, &case, base);
        let got = got(&o, &[(&cwd, "{cwd}"), (ROOT, "{root}"), (TMP, "{tmp}")]);
        if let Some(d) = diff(&want, &got) {
            failures.push(format!(
                "{}:\n{d}",
                case_dir.file_name().unwrap().to_string_lossy()
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} configs differ from PHPStan:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

#[test]
fn corpus_configs() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap();
    let vendor = root.join(".oracle/phpstan/vendor");
    assert!(
        vendor.is_dir(),
        "needs .oracle/phpstan (context/reference/oracle.md)"
    );
    let mut failures = Vec::new();
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/config-corpus");
    let mut names: Vec<String> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    for name in &names {
        // corpus/larastan (its main branch) registers a service whose class the oracle's Larastan v3.10.0 lacks, so
        // PHPStan stops creating the container; Pun resolves parameters only and never loads service classes.
        if name == "larastan.json" {
            continue;
        }
        let case = fixture(&format!("config-corpus/{name}"));
        let project = root.join("corpus").join(case["project"].as_str().unwrap());
        assert!(
            project.is_dir(),
            "needs corpus/{} (scripts/corpus.sh)",
            case["project"]
        );
        let farm =
            std::env::temp_dir().join(format!("pun-phpstan-farm-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&farm);
        std::fs::create_dir_all(&farm).unwrap();
        for entry in std::fs::read_dir(&project).unwrap() {
            let entry = entry.unwrap();
            if entry.file_name() != "vendor" {
                std::os::unix::fs::symlink(entry.path(), farm.join(entry.file_name())).unwrap();
            }
        }
        std::os::unix::fs::symlink(&vendor, farm.join("vendor")).unwrap();
        let cwd = farm.to_string_lossy().into_owned();
        // What `vendor/bin/phpstan` finds in a project (no extension-installer in .oracle/phpstan).
        let o = options(&farm, &case, Options::for_project(&cwd));
        let repo = root.to_string_lossy();
        // In a git worktree .oracle links to the main checkout's, so the phar paths resolve there: map that
        // directory to {repo}/.oracle like the fixtures (recorded from the main checkout) spell it.
        let oracle = root.join(".oracle").canonicalize().unwrap();
        let oracle = oracle.to_string_lossy();
        let got = got(
            &o,
            &[
                (&cwd, "{cwd}"),
                (&oracle, "{repo}/.oracle"),
                (&repo, "{repo}"),
                (TMP, "{tmp}"),
            ],
        );
        if let Some(d) = diff(&case["expected"], &got) {
            failures.push(format!("{name}:\n{d}"));
        }
        std::fs::remove_dir_all(&farm).unwrap();
    }
    assert!(
        failures.is_empty(),
        "{} of {} corpus configs differ from PHPStan:\n{}",
        failures.len(),
        names.len(),
        failures.join("\n")
    );
}

/// PHPStan finds an unreadable `phpstan.neon` with `is_file()` and then fails to read it; it does not fall back to
/// `phpstan.neon.dist` (`scripts/phpstan-config.php` on such a directory).
#[cfg(unix)]
#[test]
fn unreadable_default_config() {
    use std::os::unix::fs::PermissionsExt;
    let dir = std::env::temp_dir().join(format!("pun-phpstan-unreadable-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let dir = dir.canonicalize().unwrap();
    let neon = dir.join("phpstan.neon");
    std::fs::write(&neon, "parameters:\n  level: 3\n").unwrap();
    std::fs::write(dir.join("phpstan.neon.dist"), "parameters:\n  level: 5\n").unwrap();
    std::fs::set_permissions(&neon, std::fs::Permissions::from_mode(0o000)).unwrap();
    // (root reads it anyway)
    let readable = std::fs::read(&neon).is_ok();
    let o = Options {
        cwd: dir.to_string_lossy().into_owned(),
        phar: format!("{ROOT}/phpstan.phar"),
        ..Options::default()
    };
    let got = resolve(&o)
        .map(|_| ())
        .map_err(|e| e.replace(&*dir.to_string_lossy(), "{cwd}"));
    std::fs::remove_dir_all(&dir).unwrap();
    if !readable {
        assert_eq!(
            got,
            Err("File '{cwd}/phpstan.neon' is missing or is not readable.".into())
        );
    }
}
